declare module 'vexo-analytics' {
  /**
   * Initializes Vexo
   *
   * @param {string} apiKey - The app's API key
   * 
   * Check out {@link https://docs.vexo.co} for more information.
   */
  export function vexo(apiKey: string): void

  /**
   * Assigns a custom unique identifier to the device
   *
   * @param {string | null} id - Identifier
   * 
   * Check out {@link https://docs.vexo.co/features} from more information.
   */
  export function identifyDevice(id: string | null): Promise<void>

  /**
   * Enables tracking of user events
   * 
   * Check out {@link https://docs.vexo.co/features} from more information.
   */
  export function enableTracking(): Promise<void>

  /**
   * Disables tracking of user events
   * 
   * Check out {@link https://docs.vexo.co/features} from more information.
   */
  export function disableTracking(): Promise<void>

  /**
   * Creates a custom event
   * 
   * @param {string} name - Name of the event
   * @param {object} args - Additional arguments
   * 
   * Check out {@link https://docs.vexo.co/features} from more information.
   */
  export function customEvent(name: string, args: object): void
}